SELECT g.id, g.parent_id, g.name, g.grade_value, g.unit_label, g.display_order, g.active, 0 AS user_count
FROM emp_grades g
WHERE g.id = #{id}

SELECT g.id, g.parent_id, g.name, g.grade_value, g.unit_label, g.display_order, g.active, 0 AS user_count
FROM emp_grades g
WHERE g.name = #{name}

    AND g.parent_id IS NULL
    AND g.parent_id = #{parentId}

LIMIT 1

SELECT COALESCE(MAX(display_order), 0) FROM emp_grades


    parent_id IS NULL
    parent_id = #{parentId}

